import numpy as np
from scipy.optimize import minimize

def objective(a):
    return -np.sum(a**2)

def constraint_sum_cubes(a):
    return np.sum(a**3)

def solve_for_n(n):
    bound = 2 / np.sqrt(n)
    # Try multiple starting points
    best_s = 0
    for _ in range(10):
        a0 = np.random.uniform(-bound, bound, n)
        cons = [{'type': 'eq', 'fun': constraint_sum_cubes}]
        # bounds = [(None, bound)] * n
        res = minimize(objective, a0, method='SLSQP', 
                       constraints=cons, bounds=[(None, bound)] * n)
        if res.success:
            best_s = max(best_s, -res.fun)
    return best_s

for n in range(2, 11):
    print(f"n={n}, max_S={solve_for_n(n)}")
